contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function with parameters driving the contract
    function run(address initVADER, address initUSDV, address initVAULT, address recipient, uint amount) public payable {
        // require a sane non-zero proposal recipient to avoid trivial zero-address checks in grant paths
        require(initVADER != address(0) && initUSDV != address(0) && initVAULT != address(0));

        // initialize c so that newGrantProposal is allowed (init can be called only once)
        c.init(initVADER, initUSDV, initVAULT);

        // record proposalCount before
        uint before = c.proposalCount();

        // create a new grant proposal with provided inputs
        c.newGrantProposal(recipient, amount);

        // read resulting proposalCount and the stored grant details
        uint after = c.proposalCount();
        // the mapping getters are public: mapPID_grant returns a tuple (recipient, amount) via the autogenerated getter
