        (address storedRecipient, uint storedAmount) = c.mapPID_grant(after);

        // Assert the general invariant: after == before + 1 and the stored grant matches the inputs
        assert(after == before + 1 && storedRecipient == recipient && storedAmount == amount);
    }

    receive() external payable {}
