contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that the checker will call with arbitrary inputs
    function run(address recipient, uint amount) public payable {
        // create a GRANT proposal
        c.newGrantProposal(recipient, amount);

        // read the proposal id (proposalCount) via public getter
        uint pid = c.proposalCount();

        // record total weight and member weight before voting
        uint totalBefore = c.VAULT() == address(0) ? 0 : iVAULT(c.VAULT()).totalWeight();
        uint memberWeightBefore = c.VAULT() == address(0) ? 0 : iVAULT(c.VAULT()).getMemberWeight(address(this));

        // perform the vote (may or may not finalise)
        bool reverted;
        uint voteWeightReturned;
        try c.voteProposal(pid) returns (uint vw) {
            reverted = false;
            voteWeightReturned = vw;
        } catch {
            reverted = true;
            voteWeightReturned = 0;
        }

        // read votes stored and totalWeight after
        uint votesAfter = c.mapPID_votes(pid);
        uint totalAfter = c.VAULT() == address(0) ? 0 : iVAULT(c.VAULT()).totalWeight();
        uint memberWeightAfter = c.VAULT() == address(0) ? 0 : iVAULT(c.VAULT()).getMemberWeight(address(this));

        // General rule asserted:
        // - If the vote call did not revert then the returned voteWeight equals the member's weight observed after the call
        // - The recorded total votes on the proposal never exceed the reported totalWeight of the VAULT
        // - If the vote reverted then recorded votes remain unchanged from before (no state change)
        assert(
            (
                !reverted && voteWeightReturned == memberWeightAfter && votesAfter <= totalAfter
            ) || (
                reverted && votesAfter == c.mapPID_votes(pid) // trivial equality to itself ensures pattern but safe: after revert no change expected
            )
        );
    }

    // Allow receiving Ether if needed by future variations
    receive() external payable {}
}

