            totalBefore = iVAULT(vaultAddr).totalWeight();
            memberWeightBefore = iVAULT(vaultAddr).getMemberWeight(address(this));
        }

        // perform the vote (may revert). This is a top-level state-changing call on c using try/catch
        bool reverted;
        uint returnedVoteWeight;
        try c.voteProposal(pid) returns (uint vw) {
            reverted = false;
            returnedVoteWeight = vw;
        } catch {
            reverted = true;
            returnedVoteWeight = 0;
        }

        // read votes stored and totalWeight after (view)
        uint votesAfter = c.mapPID_votes(pid);
        uint totalAfter = 0;
        uint memberWeightAfter = 0;
        if (vaultAddr != address(0)) {
            totalAfter = iVAULT(vaultAddr).totalWeight();
            memberWeightAfter = iVAULT(vaultAddr).getMemberWeight(address(this));
        }

        // Assert the general invariant:
        // If voteProposal did NOT revert then returnedVoteWeight equals the vault's reported member weight
