contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single entrypoint exercising proposal creation and voting
    function run(address recipient, uint amount, address proposedAddress, string calldata typeStr) public payable {
        // no preconditions on inputs; use them to create different proposal types
        // Create one GRANT proposal and one ADDRESS-type proposal (using provided typeStr)
        c.newGrantProposal(recipient, amount);
        uint pidGrant = c.proposalCount();
        c.newAddressProposal(proposedAddress, typeStr);
        uint pidAddr = c.proposalCount();

        // read votes before voting
        uint beforeGrant = c.mapPID_votes(pidGrant);
        uint beforeAddr = c.mapPID_votes(pidAddr);

        // call voteProposal for both proposals
        // capture return values and whether calls reverted
        bool revGrant;
        uint retGrant;
        try c.voteProposal(pidGrant) returns (uint v) { revGrant = false; retGrant = v; } catch { revGrant = true; retGrant = 0; }

        bool revAddr;
        uint retAddr;
        try c.voteProposal(pidAddr) returns (uint v2) { revAddr = false; retAddr = v2; } catch { revAddr = true; retAddr = 0; }

        // read votes after voting
        uint afterGrant = c.mapPID_votes(pidGrant);
        uint afterAddr = c.mapPID_votes(pidAddr);

        // General invariant: if voteProposal did not revert, the stored total votes for that proposal
