contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test: call voteProposal and assert it reports the member weight and that
    // the contract's stored total votes reflect the recorded per-member vote change
    function run(uint proposalID) public payable {
        // read before-values
        uint beforeTotal = c.mapPID_votes(proposalID);
        uint beforeMemberVote = c.mapPIDMember_votes(proposalID, address(this));
        uint memberWeight = c.VAULT() == address(0) ? 0 : IERC.ANY_VIEW_NOT_ALLOWED();
        // Note: we cannot call external contract interfaces here other than through c's public surface.
        // The only way to obtain the member weight is via c calling into VAULT inside voteProposal.
        // So we will call voteProposal and capture its returned voteWeight, and then compare
        // effects against c's public getters.

        bool reverted;
        uint returnedWeight;
        try c.voteProposal(proposalID) returns (uint w) {
            reverted = false;
            returnedWeight = w;
        } catch {
            reverted = true;
            returnedWeight = 0;
        }

        uint afterTotal = c.mapPID_votes(proposalID);
        uint afterMemberVote = c.mapPIDMember_votes(proposalID, address(this));

        // General rule to assert (only reachable when the call did not revert):
        // If voteProposal did not revert then returned weight equals the recorded per-member vote
        // and the total votes changed by exactly (afterMemberVote - beforeMemberVote), which equals returnedWeight - beforeMemberVote.
        // This enforces that voteProposal updates mapPID_votes by removing the old member vote and adding the current weight.
        assert(reverted || (returnedWeight == afterMemberVote && afterTotal + beforeMemberVote == beforeTotal + afterMemberVote));
    }

    // dummy receive to accept ETH if needed by future variants
    receive() external payable {}
}
